async function startServerPage(){
 let state=null;
 try{const saved=sessionStorage.getItem('hp-server-update');sessionStorage.removeItem('hp-server-update');if(saved){const value=JSON.parse(saved);if(value.expires>Date.now()&&typeof value.token==='string'&&value.token)state=value;}}catch{}
 let restored=await restoreServerSession();
 // Preserve the older explicit Update-button handoff on the first upgrade.
 if(!restored&&state){
  token=state.token;
  try{me=await api('me');rememberServerSession({token,user:me,expires_at:Math.floor(Date.now()/1000)+43200});restored=true;}
  catch(error){if(error.status!==401){token='';me=null;throw error;}forgetServerSession();}
 }
 if(restored){
  if(state&&state.token===token){tab=state.tab;mobileTab=state.mobileTab;dataTeam=state.dataTeam;cableWorkFilter=state.cableWorkFilter||'inspection';reportMonth=state.reportMonth||'*';}
  else applySignedInRoute();
  await home();
  if(state&&state.token===token){try{await restoreFolderView(state.view);}catch(error){msg('Đã cập nhật, nhưng không mở lại được thư mục: '+error.message);return;}window.scrollTo(0,Number(state.scrollY)||0);msg('Đã cập nhật giao diện và dữ liệu.');}
  return;
 }
 const status=await api('status');await auth(status.needs_setup);
}
run(startServerPage);




function reportIsComplete(payload){return typeof payload?.completed==='boolean'?payload.completed:payload?.report?.completed===true;}
function markCompleted(node,done){node.classList.toggle('report-completed',done);if(done)node.title='Đã hoàn thành';else node.removeAttribute('title');}
async function markFolderCompletion(items){
 const queue=[...items];await Promise.all(Array.from({length:Math.min(4,queue.length)},async()=>{
  while(queue.length){const {folder,node}=queue.shift();if(!node.isConnected)continue;
   try{const r=await api('mobile/folders/'+folder.id);if(node.isConnected)markCompleted(node,reportIsComplete(r.payload));}catch{/* Keep the list available if one report cannot be loaded. */}
  }
 }));
}


