async function restoreFolderView(view,background=false){
 if(!view?.id)return;
 try{
  if(view.kind==='task'){
   const {tasks}=await api('mobile/cable-tasks');const index=tasks.findIndex(t=>t.id===view.id);
   if(index<0)throw Error('Tuyến không còn trong danh sách.');await openCableTask(tasks[index],index+1);
  }else if(view.kind==='folder'){
   const {folders}=await api(me.role==='admin'?'mobile/admin':'mobile/folders');
   const shown=folders.filter(f=>f.module===mobileTab&&!f.task_id&&(dataTeam==='*'||(f.team||'')===dataTeam));
   const index=shown.findIndex(f=>f.id===view.id);if(index<0)throw Error('Thư mục không còn trong danh sách.');await openMobileFolder(shown[index],index,background);
  }
 }catch(error){await home();throw error;}
}

