 if(currentToken!==token)return;
 const dialog=el('dialog'),box=el('section',undefined,'panel'),status=el('p','');dialog.append(box);
 box.append(el('h2','Người cùng làm'),el('p',record.payload.name),el('p','Chọn người được chụp thêm ảnh vào báo cáo này. Mỗi người dùng tài khoản riêng; thông tin báo cáo và hoàn thành do người tạo hoặc quản trị xử lý.','hint'));
 const selected=new Set(state.members.map(u=>u.id)),all=new Map();
 for(const u of [...state.candidates,...state.members])all.set(u.id,u);
 const inputs=[];
 for(const u of all.values())inputs.push([u.id,check(box,u.display_name,selected.has(u.id))]);
 if(!inputs.length)box.append(el('p','Chưa có người phù hợp. Quản trị cần cấp quyền loại báo cáo và Team / Đội cho thành viên.','hint'));
 box.append(status);
 let saving=false;
 const cancel=button('Đóng',()=>dialog.close()),save=button('Lưu người cùng làm',async()=>{
  if(saving||currentToken!==token)return;saving=true;save.disabled=true;cancel.disabled=true;inputs.forEach(([,input])=>input.disabled=true);status.textContent='Đang lưu…';
  try{await api('mobile/folders/'+folder.id+'/collaborators','PUT',{revision:state.revision,users:inputs.filter(([,input])=>input.checked).map(([id])=>id)});dialog.close();msg('Đã lưu người cùng làm. Thành viên mở Server → Đồng bộ trên điện thoại để nhận báo cáo chung.');}
  catch(e){status.textContent=e.message;}
  finally{saving=false;save.disabled=false;cancel.disabled=false;inputs.forEach(([,input])=>input.disabled=false);}
 },'primary');
 dialog.addEventListener('cancel',e=>{if(saving)e.preventDefault()});dialog.onclose=()=>dialog.remove();box.append(save,cancel);document.body.append(dialog);dialog.showModal();
