function combinedCableRecord(task,index,records){
  const photos=records.flatMap(({member,record})=>[...record.payload.photos].sort((a,b)=>a.seq-b.seq).map(p=>({...p,note:[p.note,'Người thực hiện: '+member.author+' · STT tại máy: '+p.seq].filter(Boolean).join('\n')}))).map((p,i)=>({...p,seq:i+1}));

  return {exportIndex:index,payload:{version:1,module:'cable',name:task.name,photos,report:{points:Object.fromEntries(records.flatMap(({record})=>[...record.payload.photos].sort((a,b)=>a.seq-b.seq).map(p=>record.payload.report?.points?.[p.seq]||{})).map((q,i)=>[i+1,q])),cableWork:true,workType:task.work_type,routeName:task.name,lengthKm:task.length_km,team:task.team,reporter:records.filter(x=>x.record.payload.photos.length).map(x=>x.member.author).join(', '),patrolDate:records.map(x=>x.record.payload.report?.patrolDate).filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i).join(', ')}}};

}
async function exportCableBatch(chosen,format){
 const files=Object.create(null);let entry=0;
 for(const {task,index}of chosen){
  msg('Đang chuẩn bị tuyến '+task.name);
  const records=[];
  for(const member of task.members){
   const record=await api('mobile/folders/'+member.folder);records.push({member,record});
  }
  const ready=task.mode==='merged'&&(canManage()||readOnly())?[combinedCableRecord(task,index+1,records)]:records.map(({member,record})=>({...record,payload:{...record.payload,name:task.name+' - '+member.author}}));
  if(!ready.length)throw Error(task.name+': Chưa có kết quả để xuất.');
  for(const record of ready){
   const prefix=String(++entry).padStart(3,'0')+' - ';
   for(const ext of format==='both'?['xlsx','kmz']:[format]){
    try{const output=await exportMobileFolder(record,ext,true);files[prefix+output.name]=output.bytes;}
    catch(e){throw Error(task.name+': '+e.message)}
   }
  }
 }
 const bytes=fflate.zipSync(files,{level:0}),url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'}));
 const link=el('a');link.href=url;link.download='Tuan-tuyen-'+chosen.length+'-tuyen-'+format+'.zip';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);msg('Đã xuất '+chosen.length+' tuyến trong một file ZIP.');
}

