 const status=el('p','Đang đọc thông tin báo cáo…','hint'),list=el('div',undefined,'list');const selectionBox=el('details'),selectionTitle=el('summary','Chọn báo cáo');selectionBox.append(selectionTitle,list);panel.append(status);
 const exportButton=button('Xuất Excel tổng hợp',async()=>{const chosen=shown.filter(x=>selected.has(x.id));if(!chosen.length)throw Error('Chọn ít nhất một báo cáo.');const missing=chosen.filter(x=>!HPSummary.values(x,1)[2]).length;if(missing&&!confirm(`${missing} báo cáo chưa xác định Tỉnh/Thành. Vẫn xuất và để trống các ô thiếu?`))return;const bytes=HPSummary.xlsx(chosen,period.value),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=el('a');a.href=url;a.download='Tong-hop-'+(kind.value==='incident'?'Su-co':'Di-doi')+'-'+period.value+'.xlsx';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);msg('Đã xuất '+a.download);},'primary');exportButton.disabled=true;panel.append(exportButton,selectionBox);
 const records=[];for(let i=0;i<source.length;i+=5){const batch=await Promise.all(source.slice(i,i+5).map(async f=>({...await api('mobile/folders/'+f.id),id:f.id,author:f.author,team:f.team})));records.push(...batch);}
  let shown=[],selected=new Set();
  const preview=el('section',undefined,'summary-preview');panel.append(preview);
  let previewKind=summaryKind;
  function drawPreview(){renderSummaryPreview(preview,shown.filter(x=>selected.has(x.id)),period.value,previewKind,type=>{previewKind=type;drawPreview();},()=>refresh());exportButton.disabled=!selected.size;}
 function refresh(preserve=false){const previous=new Set(selected),known=new Set(shown.map(x=>x.id));exportButton.textContent='Xuất Excel '+names[kind.value];list.replaceChildren();shown=records.filter(x=>HPSummary.month(x)===period.value&&x.payload.module===kind.value&&(team.value==='all'||(x.team||'')===team.value)).sort((a,b)=>HPSummary.when(a)-HPSummary.when(b));selected=new Set(shown.filter(x=>!preserve||previous.has(x.id)||!known.has(x.id)).map(x=>x.id));exportButton.disabled=!shown.length;const undated=records.filter(x=>!HPSummary.month(x)).length;status.textContent=shown.length+' báo cáo trong tháng'+(undated?` · ${undated} báo cáo thiếu ngày, chưa thể xếp tháng.`:'');const all=check(list,'Chọn tất cả',selected.size===shown.length),checks=[];all.onchange=()=>{for(const {x,input}of checks){input.checked=all.checked;if(all.checked)selected.add(x.id);else selected.delete(x.id);}drawPreview();};for(const x of shown){const province=HPSummary.values(x,1)[2],input=check(list,`${names[x.payload.module]} · ${x.payload.name} · ${x.author||''} · ${province||'Chưa có Tỉnh/Thành'}`,selected.has(x.id));input.onchange=()=>{if(input.checked)selected.add(x.id);else selected.delete(x.id);all.checked=selected.size===shown.length;drawPreview();};checks.push({x,input});}drawPreview();}
  for(const type of ['incident','relocation']){const b=button(type==='incident'?'Tổng hợp Sự cố':'Tổng hợp Di dời',()=>{kind.value=type;summaryKind=type;previewKind=type;const path=type==='incident'?'/tonghop/suco':'/tonghop/didoi';requestedAdminPath=path;history.pushState(null,'',path);for(const child of kindTabs.children)child.classList.toggle('active',child===b);refresh();},type===kind.value?'active':'');kindTabs.append(b);}
 period.onchange=()=>refresh();team.onchange=()=>refresh();refresh();
